          "body": "<b>科技社会学</b>看到的不只是一艘船，而是一整套被攻克的高端制造能力。大型邮轮被称为「漂浮的海上城市」，涉及数百个系统、上百万零部件的集成，是造船工业金字塔尖的产品。国产大型邮轮从零到一，意味着我国补齐了船舶工业最后一块高端拼图，带动材料、电子、内装等产业链整体跃升。技术自主从来不只是「争口气」，更是把就业、税收与产业话语权留在自己手里。",
