      "source": "综合新闻",
      "url": "https://www.163.com/dy/article/L48M1C6V0544TTW6.html",
      "kicker": "教育 · 教育社会学 / 情绪劳动",
      "gist": "西南医科大学一辅导员在群内称「舍不得买新教材可休学退学」，校方通报其情绪失控、言语失当并责令致歉，事件折射个别教育者角色错位与情绪劳动长期被忽视。",
      "thread": [
        {
          "t": "8月11日",
          "x": "中西医结合学院辅导员杜某在535人年级群要求统一买新教材，称「不舍得买就休学退学」。"
        },
        {
          "t": "8月13日",
          "x": "西南医科大学通报：该辅导员情绪失控、言语失当，已批评教育并责令群内致歉。"
        },
        {
          "t": "追问",
          "x": "舆论指向教材代购「自愿选购」政策在基层被异化，及辅导员心理支持缺位。"
        }
      ],
      "interpretations": [
        {
          "q": "老师一句话，怎么就伤了人？",
          "naive": "老师也是人，偶尔说错话而已，不必上纲上线。",
          "lens": "情绪劳动",
          "lensId": "emotional_labor",
          "body": "<b>情绪劳动</b>理论揭示，辅导员的工作本质是持续向他人提供情绪价值、保持克制与理性，长期处于高负荷高责任状态。当这套情绪劳动缺乏出口与制度支持，压力便会在一个点上失控，化作对学生的失当言语。更深层的是角色错位：教育者本应是「引路人」，却滑向以「退学」相威胁的管控者。一句伤人的话，表面是个人失态，底下是政策执行末梢的认知偏差与心理支持系统的双重缺失。",
          "aha": "顿悟在于：我们总要求学生心理健康，却常忘了站在讲台前的那个人也需要被看见、被托住——教育的温度，先从善待教育者开始。"
        }
      ],
