          "lens": "道德风险",
          "lensId": "econ_moral_hazard",
          "body": "<b>道德风险</b>指一方在信息或监督占优时，为自身利益损害他方却难被追责。量贩零食加盟店遍布全国、扩张迅猛，总部对末梢门店的计量行为难以实时监督；消费者自带秤复称的成本高、多数人懒得较真，于是「秤上做手脚」的预期代价极低。当违规收益归门店、风险与声誉成本却由品牌与顾客共担，个别门店便有动力钻空子。缺斤少两卖的不是牛肉干，而是消费者好不容易建立的信任。",
          "aha": "顿悟在于：你以为只占了几两便宜，实则透支的是整块招牌的信用——信任一旦称没，再多门店也填不回那个窟窿。"
