          "body": "<b>风险社会理论</b>指出，现代灾害很少是纯粹「天灾」，而是自然变量与人类建成环境叠加的产物。民堤标准低、维护弱，本就在日常埋下隐患；当极端降雨来袭，薄弱处便率先决口。风险从来偏爱最脆弱的环节与最弱势的群体——中小河流、偏远乡镇往往防护最薄。治理不能只在溃口后抢险，更要在平日把堤防、预警与转移预案织密，让风险被提前分流。",
