          "body": "<b>工作社会学</b>提醒，事故从不是孤立的「意外」，而是劳动组织、管理制度与执行层层失守的结果。有限空间作业本有通风、检测、审批等规程，但当产能压力压过安全流程、培训与监督流于形式，规程便成了墙上的摆设。3条生命的逝去，暴露的是风险岗位上劳动者议价权与防护权的双重薄弱——他们往往最没能力拒绝一次违规的「快干」。安全若只靠个人小心，终究敌不过系统的松懈。",
