          "lens": "教育社会学",
          "lensId": "education",
          "body": "<b>教育社会学</b>关注教育资源如何分配、由谁承担。公办校以编外「课时服务人员」补位，表面解了人手之急，却把公共服务的质量与稳定系于一群待遇低、保障弱的岗位之上。当核心教学支持依赖脆弱用工，受影响最深的往往是资源本就紧张的学校与学生——公平的天平在「省钱」与「保质」之间悄悄倾斜。真正的教育公平，不只是让孩子都有学上，更是让每一间教室背后都有稳固、被尊重的支撑力量。",
