          "lens": "需求层次",
          "lensId": "psy_needs",
          "body": "马斯洛将生理需求置于需求金字塔的底层，但正是在极端环境中，这一“低级”需求才凸显其根本性。电影中“好好吃饭”不仅是生存行为，更成为<b>尊严与希望</b>的隐喻。当炮火撕裂日常，一碗热饭便是文明的底线，是人性不灭的证明。",
